package vn.rtr.aeris.mission;
import android.system.*;import java.io.*;import java.nio.channels.*;
/** Actual Android descriptor facts; host JVM tests do not substitute for these. */
public final class JournalAndroidBoundary17 extends JournalGuard17.Boundary {
 private static JournalGuard17.Fact fact(StructStat s){return new JournalGuard17.Fact(s.st_dev,s.st_ino,s.st_nlink,OsConstants.S_ISREG(s.st_mode),OsConstants.S_ISDIR(s.st_mode));}
 @Override public JournalGuard17.Fact fact(File f)throws IOException{try{return fact(Os.lstat(f.getPath()));}catch(Exception e){throw new IOException("JOURNAL17_LSTAT",e);}}
 @Override public byte[] readRange(File f,long offset,int count,int maximum)throws IOException{JournalGuard17.Fact before=fact(f);regular(f);if(offset<0||count<0||count>maximum||offset+count>f.length())throw new IOException("JOURNAL17_READ_BOUND");FileDescriptor fd=null;IOException primary=null;try{fd=Os.open(f.getPath(),OsConstants.O_RDONLY|OsConstants.O_NOFOLLOW,0);JournalGuard17.Fact opened=fact(Os.fstat(fd));if(!before.same(opened))throw new IOException("JOURNAL17_FD_OPEN_IDENTITY");byte[] b=new byte[count];Os.lseek(fd,offset,OsConstants.SEEK_SET);int at=0;while(at<count){int n=Os.read(fd,b,at,count-at);if(n<=0)throw new IOException("JOURNAL17_TORN_READ");at+=n;}if(!opened.same(fact(Os.fstat(fd)))||!opened.same(fact(f)))throw new IOException("JOURNAL17_FD_READ_IDENTITY");return b;}catch(Exception e){primary=e instanceof IOException?(IOException)e:new IOException("JOURNAL17_NOFOLLOW_READ",e);throw primary;}finally{if(fd!=null)try{Os.close(fd);}catch(Exception e){IOException secondary=new IOException("JOURNAL17_FD_CLOSE",e);if(primary!=null)primary.addSuppressed(secondary);else throw secondary;}}}
 @Override public FileOutputStream append(File f)throws IOException{FileDescriptor fd=null;try{JournalGuard17.Fact before=fact(f);regular(f);fd=Os.open(f.getPath(),OsConstants.O_WRONLY|OsConstants.O_APPEND|OsConstants.O_NOFOLLOW,0);JournalGuard17.Fact opened=fact(Os.fstat(fd));if(!before.same(opened)||!opened.same(fact(f)))throw new IOException("JOURNAL17_APPEND_FD_IDENTITY");return new OwnedOutput(fd);}catch(Exception e){if(fd!=null)try{Os.close(fd);}catch(Exception ignored){}throw new IOException("JOURNAL17_APPEND_NOFOLLOW",e);}}
 @Override public FileOutputStream exclusive(File f)throws IOException{FileDescriptor fd=null;try{fd=Os.open(f.getPath(),OsConstants.O_WRONLY|OsConstants.O_CREAT|OsConstants.O_EXCL|OsConstants.O_NOFOLLOW,0600);JournalGuard17.Fact opened=fact(Os.fstat(fd));if(!opened.regular||opened.links!=1||!opened.same(fact(f)))throw new IOException("JOURNAL17_EXCLUSIVE_FD_IDENTITY");return new OwnedOutput(fd);}catch(Exception e){if(fd!=null)try{Os.close(fd);}catch(Exception ignored){}throw new IOException("JOURNAL17_EXCLUSIVE_NOFOLLOW",e);}}
 private static final class OwnedOutput extends FileOutputStream{private final FileDescriptor owned;OwnedOutput(FileDescriptor fd){super(fd);owned=fd;}@Override public void close()throws IOException{super.close();if(owned.valid())try{Os.close(owned);}catch(Exception e){throw new IOException("JOURNAL17_OWNED_FD_CLOSE",e);}}}
 @Override public JournalGuard17.LockFile lockFile(File f)throws IOException{FileDescriptor fd=null;try{fd=Os.open(f.getPath(),OsConstants.O_RDWR|OsConstants.O_CREAT|OsConstants.O_NOFOLLOW,0600);JournalGuard17.Fact opened=fact(Os.fstat(fd));if(!opened.regular||opened.links!=1||!opened.same(fact(f)))throw new IOException("JOURNAL17_LOCK_FD_IDENTITY");OwnedOutput out=new OwnedOutput(fd);return new JournalGuard17.LockFile(out.getChannel(),out);}catch(Exception e){if(fd!=null)try{Os.close(fd);}catch(Exception ignored){}throw new IOException("JOURNAL17_LOCK_NOFOLLOW",e);}}
 @Override public void capacity(File root,long add)throws IOException{super.capacity(root,add);long[] totals={0,0,0};count(root,totals);if(totals[0]+add>512L*1024*1024||totals[1]+add+32768>160L*1024*1024)throw new IOException("JOURNAL17_WHOLE_NATIVE_QUOTA");}
 private void count(File f,long[] totals)throws IOException{if(++totals[2]>8192)throw new IOException("JOURNAL17_NATIVE_ENTRY_BOUND");try{StructStat s=Os.lstat(f.getPath());if(OsConstants.S_ISREG(s.st_mode)){if(s.st_nlink!=1)throw new IOException("JOURNAL17_NATIVE_HARDLINK");totals[0]+=s.st_size;totals[1]+=s.st_blocks*512;}else if(OsConstants.S_ISDIR(s.st_mode)){totals[1]+=s.st_blocks*512;File[] children=f.listFiles();if(children==null)throw new IOException("JOURNAL17_NATIVE_LIST");for(File x:children)count(x,totals);}else throw new IOException("JOURNAL17_NATIVE_NONREGULAR");}catch(ErrnoException e){throw new IOException("JOURNAL17_NATIVE_LSTAT",e);}}
}
